 // 쪼로록: 맨 앞 보석이 길을 내고, 뒤 보석들은 앞 보석이 지나간 자리를 그대로 따라감
 function chainOrder(list,first){const rest=list.filter(j=>j!==first),out=[first];while(rest.length){const p=out[out.length-1],px=p%st.w,py=Math.floor(p/st.w);let b=0,bd=1e9;for(let k=0;k<rest.length;k++){const j=rest[k],dd=(j%st.w-px)**2+(Math.floor(j/st.w)-py)**2;if(dd<bd){bd=dd;b=k;}}out.push(rest.splice(b,1)[0]);}return out;}
 // 토도도독: 한 알씩 차례로 짧게 날아감 (원작처럼 앞 알이 거의 도착할 즈음 다음 알 출발)

