 function renderTray(){buildHoles();const T=S.tray.concat(...[...ghostT].map(([c,n])=>Array(n).fill(c))).sort((a,b)=>a-b),tot=new Map(),seen=new Map();for(const v of T)tot.set(v,(tot.get(v)||0)+1);
  holes.forEach((h,k)=>{const v=k<T.length&&k<S.cap?T[k]:-1,i=h.firstChild;h.dataset.c=v;h.classList.toggle('sel',v>=0&&v===selT);if(v<0){i.hidden=true;i.dataset.c='';return;}
   const n=seen.get(v)||0;seen.set(v,n+1);if(n>=tot.get(v)-(pend.get(v)||0)){i.hidden=true;i.dataset.c='';return;}
   if(i.hidden||i.dataset.c!==String(v)){const was=!i.hidden;i.hidden=false;i.dataset.c=v;const c=st.pal[v];i.style.backgroundImage=`url(${gemURL(c)})`;if(!was){i.classList.remove('pop');void i.offsetWidth;i.classList.add('pop');}}});
  $('cap').textContent=`${S.tray.length} / ${S.cap}`;}
 function renderTop(){$('lv').textContent=`단계 ${data.lv}`;}
